#!/usr/bin/env bash
set -euo pipefail
root=/var/lib/steam-top-bootstrap/install-receipts;config=/etc/steam-top-bootstrap/trust.json;[[ $(id -u) -eq 0 && $# -eq 0 && -d $root && ! -L $root && $(stat -c '%u %a' "$root") == '0 700' ]]||exit 1;source /opt/steam-top-bootstrap/key-custody-guard.sh;key_private_file "$config"||exit 1;mapfile -t generations < <(find "$root" -mindepth 1 -maxdepth 1 -type d ! -name '.*' -print);[[ ${#generations[@]} -eq 1 ]];generation=${generations[0]};payload=$generation/payload.json;sig=$payload.sig;[[ -f $payload && ! -L $payload && -f $sig && ! -L $sig && $(stat -c '%u %a' "$payload") == '0 400' && $(stat -c '%u %a' "$sig") == '0 400' && $(stat -c '%u %a' "$generation") == '0 500' ]];allowed=$(node -p 'require(process.argv[1]).productionStateAllowedSigners' "$config");key_allowed_signers_file "$allowed"||exit 1;signer=$(node -p 'require(process.argv[1]).signerKeyId' "$payload");[[ $signer =~ ^[A-Za-z0-9@._-]+$ ]];ssh-keygen -Y verify -q -f "$allowed" -I "$signer" -n steam-top-bootstrap-install -s "$sig" <"$payload";receipt_digest=$(sha256sum "$payload"|awk '{print $1}');[[ $(basename "$generation") == "$receipt_digest" ]];host=$(cat /etc/machine-id 2>/dev/null||hostname);host=$(printf %s "$host"|openssl dgst -sha256|awk '{print $NF}');bootstrap=$(sha256sum /opt/steam-top-bootstrap/bootstrap-files.sha256|awk '{print $1}');installer=$(sha256sum /opt/steam-top-bootstrap/install-bootstrap.sh|awk '{print $1}');node -e 'const x=require(process.argv[1]),keys=Object.keys(x).sort(),expected=["bootstrapDigest","createdAt","hostId","initNonce","installerDigest","purpose","schemaVersion","signerKeyId"].sort();if(JSON.stringify(keys)!==JSON.stringify(expected)||x.schemaVersion!==1||x.purpose!=="steam-top-bootstrap-install-receipt"||x.hostId!==process.argv[2]||x.bootstrapDigest!==process.argv[3]||x.installerDigest!==process.argv[5]||!(/^[a-f0-9]{64}$/.test(x.initNonce))||!(/^[A-Za-z0-9@._-]+$/.test(x.signerKeyId))||!Number.isFinite(Date.parse(x.createdAt)))process.exit(1);console.log([process.argv[4],x.initNonce,x.hostId,x.bootstrapDigest].join(" "))' "$payload" "$host" "$bootstrap" "$receipt_digest" "$installer"
